/**
 * @name Taint tracking to subprocess calls in _termui_impl.py
 * @description Track taint from function parameters to subprocess calls in _termui_impl.py
 * @kind path-problem
 * @problem.severity error
 * @id py/termui-subprocess-taint
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SubprocessTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall() and
      sink = call.getArg(0) and
      call.getLocation().getFile().getShortName() = "_termui_impl.py"
    )
  }
}

module SubprocessTaintFlow = TaintTracking::Global<SubprocessTaintConfig>;
import SubprocessTaintFlow::PathGraph

from SubprocessTaintFlow::PathNode source, SubprocessTaintFlow::PathNode sink
where SubprocessTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Subprocess argument derived from parameter $@.", source.getNode(), "parameter"
